mapper.select:
select coalesce(sum(), 0)
from transaction t
where t.transaction_date >= #{since,jdbcType=DATE}
and t.consume_code = #{categoryCode,jdbcType=VARCHAR}

select coalesce(sum(), 0)
from transaction t
left join cls_category cat on cat.code = t.consume_code and cat.deleted != 1
where t.transaction_date >= #{start,jdbcType=DATE}
and t.transaction_date <= #{end,jdbcType=DATE}

select coalesce(sum(), 0)
from transaction t
where t.transaction_date >= #{start,jdbcType=DATE}
and t.transaction_date <= #{end,jdbcType=DATE}
and t.consume_code = #{categoryCode,jdbcType=VARCHAR}
